    /**
     * @param Integer[] $nums
     * @param Integer $goal
     * @return Integer
     */
    function minAbsDifference($nums, $goal) {
        $n = count($nums);
        $half = intdiv($n, 2);

        // Generate all possible subsequence sums for a part of the array
        function getSums($arr) {
            $res = [0];
            foreach ($arr as $num) {
                $newSums = [];
                foreach ($res as $sum) {
                    $newSums[] = $sum + $num;
                }
                $res = array_merge($res, $newSums);
            }
            return $res;
        }

        $leftArr = array_slice($nums, 0, $half);
        $rightArr = array_slice($nums, $half);

        $leftSums = getSums($leftArr);
        $rightSums = getSums($rightArr);
        sort($rightSums);

        $minDiff = PHP_INT_MAX;

        // For each sum in left sums, find the best matching sum in right sums to get close to goal
        foreach ($leftSums as $sumLeft) {
            $target = $goal - $sumLeft;

            // Binary search in rightSums for value closest to target
            $low = 0;
            $high = count($rightSums) - 1;

            while ($low <= $high) {
                $mid = intdiv($low + $high, 2);
                if ($rightSums[$mid] < $target) {
                    $low = $mid + 1;
                } else {
                    $high = $mid - 1;
                }
            }

            // Check sums around insertion position low and high for the best difference
            if ($low < count($rightSums)) {
                $minDiff = min($minDiff, abs($sumLeft + $rightSums[$low] - $goal));
                if ($minDiff == 0) return 0;
            }
            if ($low - 1 >= 0) {
                $minDiff = min($minDiff, abs($sumLeft + $rightSums[$low - 1] - $goal));
                if ($minDiff == 0) return 0;
            }
        }

        return $minDiff;
    }
